"""The module and item names of a wasm import."""
@parity "dart2wasm/lib/util.dart:87 ImportName" struct ImportName
    module_name::String
    item_name::String
    # the struct's one constructor, tagged; dart's constructor at :91 is its outer function
    ImportName(::Val{:_}, module_name::String, item_name::String) = new(module_name, item_name)
end

